String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    int i = 0;
    int len = str.length();
    while (i < len) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            if (i >= len) {
                throw new Exception("Invalid escape sequence");
            }
            char next = str.charAt(i);
            switch (next) {
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    // Handle Unicode escape sequences
                    if (next == 'u') {
                        String hex = str.substring(i + 1, i + 5);
                        int hexValue = Integer.parseInt(hex, 16);
                        sb.append((char) hexValue);
                        i += 4; // Skip the hex digits
                    } else {
                        throw new Exception("Unsupported escape sequence: \\" + next);
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
        i++;
    }
    return sb.toString();
}

